use std::collections::HashSet;

fn has_common_element(a: Vec<i32>, b: Vec<i32>) -> bool {
    // If either array is empty, return false
    if a.is_empty() || b.is_empty() {
        return false;
    }

    // Create a HashSet from the first array
    let set_a: HashSet<i32> = a.into_iter().collect();

    // Check if any element in the second array exists in the HashSet
    for &element in &b {
        if set_a.contains(&element) {
            return true; // Found a common element
        }
    }

    false // No common elements found
}